const store={get(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{}}};
const state={locale:store.get('yogui-language','fr'),view:'home',kind:'all',pack:'all',q:'',disabled:false,sort:'relevance',saved:new Set(store.get('yogui-bookmarks',[])),limit:36};
let manifest,index=[],lookup=new Map(),packs=new Map(),icons={},names={},worker,workerReady=false,request=0,resultIds=[],currentEntry=null,currentChunkCache=new Map(),pendingChunkCache=new Map(),entryRequest=0,toastTimer,searchTimer,linkLimits={};
const t=key=>messages[key]?.[state.locale==='en'?1:0]||key;
const L=value=>typeof value==='object'&&value!==null?(value[state.locale]??value.en??value.fr??''):String(value??'');
const kindLabel=(kind,singular=false)=>kinds[kind]?.[state.locale==='en'?1:0]?.[singular?1:0]||kind;
const num=n=>new Intl.NumberFormat(state.locale).format(n||0);
const textBlock=value=>`<div class="prose">${esc(L(value)).split(/\n\s*\n/).map(p=>`<p>${p.replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\n/g,'<br>')}</p>`).join('')}</div>`;
const safeURL=url=>{try{const v=new URL(url,location.href);return ['http:','https:'].includes(v.protocol)?esc(v.href):'#'}catch{return '#'}};
const route=changes=>{const p=new URLSearchParams();const s={view:state.view,kind:state.kind,pack:state.pack,q:state.q,disabled:state.disabled,sort:state.sort,...changes};for(const key of ['view','kind','pack','q','sort'])if(s[key]&&s[key]!==({view:'home',kind:'all',pack:'all',q:'',sort:'relevance'}[key]))p.set(key,s[key]);if(s.disabled)p.set('disabled','1');if(s.entry)p.set('entry',s.entry);return '#'+p.toString()};
const go=changes=>{location.hash=route(changes)};
const imageTag=(src,cls='',alt='')=>src?`<img class="${cls}" src="${safeURL(src)}" alt="${esc(alt)}" loading="lazy" decoding="async" onerror="this.hidden=true">`:'';
function iconForEntry(e){let image=e.image||icons[e.id];if(!image&&e.kind==='enchantment')image=icons['minecraft:enchanted_book'];if(!image&&e.kind==='mob'){const id=e.details?.entityType||e.details?.type||e.tags?.find(s=>s.startsWith('minecraft:'));const remap={zombie:'rotten_flesh',skeleton:'bone',creeper:'gunpowder',spider:'spider_eye',witch:'potion',piglin:'gold_ingot',blaze:'blaze_rod',enderman:'ender_pearl',phantom:'phantom_membrane',wither_skeleton:'wither_skeleton_skull',allay:'amethyst_shard'};const id2=String(id||'').split(':').pop();image=icons['minecraft:'+remap[id2]];}return `<span class="entry-icon ${esc(e.kind)}">${image?imageTag(image,'',L(e.title)):icon(e.kind)}</span>`}
function packIcon(p,cls='pack-card-icon'){return p?.icon?imageTag(p.icon,cls,''):`<span class="pack-placeholder ${cls}">${icon('pack')}</span>`}
function showToast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2400)}
function save(id){if(state.saved.has(id)){state.saved.delete(id);showToast(t('removed'))}else{state.saved.add(id);showToast(t('added'))}store.set('yogui-bookmarks',[...state.saved]);renderNav();document.querySelectorAll(`[data-save]`).forEach(b=>b.classList.toggle('saved',state.saved.has(b.dataset.save)));if(currentEntry)$('#saveEntry').classList.toggle('saved',state.saved.has(currentEntry.id));if(state.view==='saved')query()}
function renderChrome(){document.documentElement.lang=state.locale;document.title=state.locale==='fr'?'YoGui · Le carnet d’aventure':'YoGui · The adventure journal';document.querySelectorAll('[data-i18n]').forEach(e=>e.textContent=t(e.dataset.i18n));$('#search').placeholder=t('searchPlaceholder');$('#search').setAttribute('aria-label',t('searchLabel'));$('#searchClear').setAttribute('aria-label',t('searchClear'));$('#menuButton').innerHTML=icon('menu');$('#menuButton').setAttribute('aria-label',t('menu'));$('#searchIcon').innerHTML=icon('search');$('#bookmarksButton').innerHTML=icon('bookmark');$('#bookmarksButton').setAttribute('aria-label',t('saved'));$('#helpIcon').innerHTML=icon('info');$('#copyEntry').innerHTML=icon('copy');$('#copyEntry').setAttribute('aria-label',t('copyLink'));$('#saveEntry').innerHTML=icon('bookmark');$('#closeEntry').innerHTML=icon('close');$('#closeEntry').setAttribute('aria-label',t('close'));document.querySelectorAll('[data-language]').forEach(b=>{const active=b.dataset.language===state.locale;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});$('#footer').innerHTML=`<span class="footer-left"><span class="status-dot"></span>YoGui · ${esc(t('footerText'))}</span><span>${esc(t('dataDate'))} · <a href="#view=about">${esc(t('aboutGuide'))}</a></span>`;renderNav()}
function navLink(label,kind,view='catalog'){const count=kind==='saved'?state.saved.size:kind==='pack'?manifest.packs.length:manifest.counts[kind];const selected=view===state.view&&(view!=='catalog'||state.kind===kind);return `<a class="nav-link ${selected?'active':''}" href="${route({view,kind:view==='catalog'?kind:'all',pack:'all',q:''})}" ${selected?'aria-current="page"':''}><span class="nav-icon">${icon(kind==='saved'?'bookmark':kind)}</span><span class="nav-label">${esc(label)}</span>${count?`<span class="nav-count">${num(count)}</span>`:''}</a>`}
function renderNav(){if(!manifest)return;$('#navigation').innerHTML=`<div class="nav-group">${navLink(t('home'),'home','home')}${navLink(t('packs'),'pack','packs')}${navLink(kindLabel('guide'),'guide')}</div><div class="nav-group-label">${t('discover')}</div><div class="nav-group">${['structure','biome','dimension','mob','loot'].map(k=>navLink(kindLabel(k),k)).join('')}</div><div class="nav-group-label">${t('equipment')}</div><div class="nav-group">${['item','enchantment','recipe'].map(k=>navLink(kindLabel(k),k)).join('')}</div><div class="nav-group-label">${t('journal')}</div><div class="nav-group">${navLink(t('allEntries'),'all')}${navLink(t('saved'),'saved','saved')}${navLink(kindLabel('module'),'module')}</div>`}
function crumb(text){return `<div class="page-crumb"><a href="#view=home">YoGui</a><span>/</span><span class="current">${esc(text)}</span></div>`}
function stat(iconName,value,label){return `<div class="summary-stat"><div class="stat-icon">${icon(iconName)}</div><div><strong>${num(value)}</strong><span>${esc(label)}</span></div></div>`}
function renderHome(){const featured=['dungeons-and-taverns','incendium','enchantments-encore','reg-more-foods','katters-structures','mine-treasure','upperwilds','moar-swords'].map(id=>packs.get(id)).filter(Boolean);$('#main').innerHTML=`${crumb(t('home'))}<section class="hero"><div class="hero-copy"><div class="eyebrow">${t('homeEyebrow')}</div><h1>${t('hero1')}<br><em>${t('hero2')}</em></h1><p class="hero-description">${t('heroDescription')}</p><div class="hero-actions"><a class="button" href="#view=catalog">${t('browse')}${icon('arrow')}</a><a class="button quiet" href="#entry=guide%3Abien-demarrer">${t('start')}</a></div></div><img class="hero-illustration" src="./assets/world.svg" alt="" width="420" height="310"></section><div class="summary-stats">${stat('pack',manifest.packs.length,t('statPacks'))}${stat('structure',manifest.counts.structure,t('statStructures'))}${stat('item',manifest.counts.item,t('statItems'))}${stat('recipe',manifest.counts.recipe,t('statRecipes'))}</div><section><div class="section-heading"><div><h2>${t('chooseAdventure')}</h2><p>${t('chooseAdventureSubtitle')}</p></div></div><div class="home-paths">${[['structure','compass','exploreTitle','exploreText'],['item','item','gearTitle','gearText'],['recipe','recipe','craftTitle','craftText']].map(([kind,i,title,desc])=>`<a class="path-card" href="#view=catalog&kind=${kind}"><div class="path-icon">${icon(i)}</div><div class="path-decor">${icon(i)}</div><h3>${t(title)}</h3><p>${t(desc)}</p><span class="path-arrow">${icon('arrow')}</span></a>`).join('')}</div></section><div class="two-columns"><section class="notice-card"><div class="eyebrow">${t('fieldNotes')}</div><h3>${t('start')}</h3><p>${t('startText')}</p><div class="guide-links"><a class="guide-link" href="#entry=guide%3Abien-demarrer">${icon('book')}${t('read')}<span class="arrow">${icon('arrow')}</span></a><a class="guide-link" href="#entry=guide%3Adimensions-et-retour">${icon('dimension')}${t('dimensionGuide')}<span class="arrow">${icon('arrow')}</span></a><a class="guide-link" href="#entry=guide%3Acomprendre-le-butin">${icon('loot')}${t('lootGuide')}<span class="arrow">${icon('arrow')}</span></a></div></section><div><a class="small-feature" href="#entry=guide%3Ajei-et-recettes"><span class="feature-icon">${icon('recipe')}</span><div><h3>${t('jeiTitle')}</h3><p>${t('jeiText')}</p></div></a><a class="small-feature" href="#view=pack&pack=the-dreaming-realm"><span class="feature-icon">${icon('dimension')}</span><div><h3>${t('dreamTitle')}</h3><p>${t('dreamText')}</p></div></a></div></div><section><div class="section-heading"><div><h2>${t('inYourWorld')}</h2><p>${t('inYourWorldSubtitle')}</p></div><a href="#view=packs">${t('seeAllPacks')}${icon('arrow')}</a></div><div class="pack-strip">${featured.map(p=>`<a class="mini-pack" href="#view=pack&pack=${encodeURIComponent(p.id)}">${packIcon(p,'')}<span><strong>${esc(L(p.title))}</strong><small>${esc(p.version)} · ${num(Object.values(p.counts||{}).reduce((a,b)=>a+b,0))} ${t('results')}</small></span></a>`).join('')}</div></section>`}
function entryCard(e){const p=packs.get(e.pack);return `<article class="entry-card ${e.status!=='active'?'disabled':''}"><a class="entry-card-main" href="${route({entry:e.id})}"><div class="entry-card-top">${iconForEntry(e)}<span class="kind-label">${esc(e.reference?t(e.missing?'missingReference':'base'):kindLabel(e.kind,true))}</span></div><h3>${esc(L(e.title))}</h3><p class="entry-card-description">${esc(L(e.summary||e.description))}</p></a><div class="entry-card-footer"><a class="entry-pack-label" href="#view=pack&pack=${encodeURIComponent(e.pack)}">${p?.icon?imageTag(p.icon,'',''):''}${esc(L(p?.title)||e.pack)}</a><button class="card-bookmark ${state.saved.has(e.id)?'saved':''}" data-save="${esc(e.id)}" aria-label="${esc(state.saved.has(e.id)?t('unsave'):t('save'))}" aria-pressed="${state.saved.has(e.id)}">${icon('bookmark')}</button></div></article>`}
function packCard(p){return `<a class="pack-card" href="#view=pack&pack=${encodeURIComponent(p.id)}"><div class="pack-card-top">${packIcon(p)}<span class="pack-version">${esc(p.version)}</span></div><h3>${esc(L(p.title))}</h3><p>${esc(L(p.summary||p.description))}</p><div class="pack-card-bottom"><span class="status-badge ${p.status!=='active'?'disabled':''}">${p.status==='active'?esc(t('active')):esc(t('disabled'))}</span>${icon('arrow')}</div></a>`}
function renderPacks(){const q=state.q.toLowerCase();const ps=manifest.packs.filter(p=>!q||JSON.stringify([p.title,p.summary,p.description]).toLowerCase().includes(q));$('#main').innerHTML=`${crumb(t('packs'))}<div class="catalog-header"><div><h1>${t('allPacksTitle')}</h1><p>${t('allPacksText')}</p></div><span class="catalog-total">${num(ps.length)} ${kindLabel('pack').toLowerCase()}</span></div><div class="pack-grid">${ps.map(packCard).join('')}</div>`}
function renderPack(){const p=packs.get(state.pack);if(!p){go({view:'packs',pack:'all'});return}const gallery=(p.gallery||[]).find(i=>i.featured)||p.gallery?.[0];$('#main').innerHTML=`${crumb(L(p.title))}<div class="pack-intro"><div><div class="pack-title-row">${packIcon(p,'')}<div><h1>${esc(L(p.title))}</h1><div class="pack-byline"><span>${esc(p.version)}</span><span class="status-badge ${p.status!=='active'?'disabled':''}">${t(p.status==='active'?'active':'disabled')}</span></div></div></div><div class="pack-prose">${textBlock(p.description)}</div><div class="pack-source-links">${p.url?`<a class="text-link" href="${safeURL(p.url)}" target="_blank" rel="noopener noreferrer">${t('officialPage')}${icon('external')}</a>`:''}${(p.sources||[]).slice(0,2).filter(s=>s.url&&s.url!==p.url).map(s=>`<a class="text-link" href="${safeURL(s.url)}" target="_blank" rel="noopener noreferrer">${esc(L(s.label)||s.label||'Wiki')}${icon('external')}</a>`).join('')}</div></div><aside>${gallery?.url?imageTag(gallery.url,'pack-cover',L(p.title)):''}<div class="pack-quick-info"><div><strong>Minecraft ${esc(manifest.minecraft)}</strong><span>${t('dataDate')}</span></div><div><strong>${t('resources'+({none:'None',optional:'Optional',required:'Required'}[p.resources]||'None'))}</strong></div></div></aside></div>${(p.gettingStarted?.length||p.tips?.length)?`<details class="pack-guide" open><summary>${t('gettingStarted')} · ${t('tips')}</summary><div class="pack-guide-body"><section><h3>${t('gettingStarted')}</h3><ul>${(p.gettingStarted||[]).map(x=>`<li>${esc(L(x))}</li>`).join('')}</ul></section><section><h3>${t('tips')}</h3><ul>${(p.tips||[]).map(x=>`<li>${esc(L(x))}</li>`).join('')}</ul></section></div></details>`:''}${p.status!=='active'?`<div class="readable-notice">${t('disabledNotice')}</div>`:''}<div class="section-heading"><div><h2>${t('packContents')}</h2></div></div>${filterMarkup(true)}<div id="results"></div>`;bindFilters();query()}
function filterMarkup(inPack=false){const allCount=Object.values(manifest.counts).reduce((a,b)=>a+b,0);const visibleKinds=['all','structure','item','enchantment','recipe','mob','loot'];return `<section class="filters" aria-label="${esc(t('filter'))}"><div class="filter-row"><span class="filter-label">${icon('filter')}${t('filter')}</span>${visibleKinds.map(k=>`<button class="chip ${state.kind===k?'active':''}" data-kind="${k}" aria-pressed="${state.kind===k}">${esc(k==='all'?t('all'):kindLabel(k))}</button>`).join('')}</div><div class="filter-row">${!inPack?`<select class="filter-select" id="packFilter" aria-label="${esc(t('packs'))}"><option value="all">${t('allPacks')}</option>${[...manifest.packs,...(manifest.referencePack?[manifest.referencePack]:[])].map(p=>`<option value="${esc(p.id)}" ${state.pack===p.id?'selected':''}>${esc(L(p.title))}</option>`).join('')}</select>`:''}<select class="filter-select" id="kindFilter" aria-label="${esc(t('allEntries'))}"><option value="all">${t('allEntries')}</option>${Object.keys(kinds).filter(k=>k!=='pack').map(k=>`<option value="${k}" ${state.kind===k?'selected':''}>${esc(kindLabel(k))}</option>`).join('')}</select><select class="filter-select" id="sortFilter" aria-label="${esc(t('relevance'))}">${[['relevance','relevance'],['name','alphabetical'],['pack','byPack']].map(([v,l])=>`<option value="${v}" ${state.sort===v?'selected':''}>${t(l)}</option>`).join('')}</select><label class="filter-checkbox"><input type="checkbox" id="disabledFilter" ${state.disabled?'checked':''}>${t('showDisabled')}</label><button class="filter-reset" id="resetFilters">${icon('close')}${t('reset')}</button></div></section>`}
function bindFilters(){document.querySelectorAll('[data-kind]').forEach(b=>b.addEventListener('click',()=>go({kind:b.dataset.kind})));$('#packFilter')?.addEventListener('change',e=>go({pack:e.target.value}));$('#kindFilter')?.addEventListener('change',e=>go({kind:e.target.value}));$('#sortFilter')?.addEventListener('change',e=>go({sort:e.target.value}));$('#disabledFilter')?.addEventListener('change',e=>go({disabled:e.target.checked}));$('#resetFilters')?.addEventListener('click',()=>go({kind:'all',pack:state.view==='pack'?state.pack:'all',q:'',disabled:false,sort:'relevance'}))}
function renderCatalog(){const title=state.q?`${t('searchResults')} « ${state.q} »`:state.view==='saved'?t('saved'):state.kind==='all'?t('catalogTitle'):kindLabel(state.kind);$('#main').innerHTML=`${crumb(state.view==='saved'?t('saved'):state.kind==='all'?t('allEntries'):kindLabel(state.kind))}<div class="catalog-header"><div><h1>${esc(title)}</h1><p>${t(state.view==='saved'?'savedText':'catalogText')}</p></div></div>${filterMarkup()}<div id="results"><div class="entry-grid">${[1,2,3].map(()=>'<div class="skeleton"></div>').join('')}</div></div>`;bindFilters();query()}
function query(){if(!workerReady)return;worker.postMessage({type:'search',request:++request,q:state.q,kind:state.kind,pack:state.pack,disabled:state.disabled||(state.view==='pack'&&packs.get(state.pack)?.status!=='active'),locale:state.locale,sort:state.sort,saved:state.view==='saved'?[...state.saved]:null})}
function renderResults(){const result=$('#results');if(!result)return;const visible=resultIds.slice(0,state.limit).map(id=>lookup.get(id)).filter(Boolean);if(!visible.length){result.innerHTML=`<div class="empty-state">${icon(state.view==='saved'?'bookmark':'search')}<h2>${t('emptyTitle')}</h2><p>${t(state.view==='saved'?'emptySaved':'emptyText')}</p>${state.view!=='saved'?`<button class="button secondary" id="emptyReset">${t('reset')}</button>`:''}</div>`;$('#emptyReset')?.addEventListener('click',()=>go({kind:'all',pack:state.view==='pack'?state.pack:'all',q:''}));return}result.innerHTML=`<div class="results-line"><span><strong>${num(resultIds.length)}</strong> ${t(resultIds.length===1?'result':'results')}</span><span>${num(visible.length)} ${t('shown')}</span></div><div class="entry-grid">${visible.map(entryCard).join('')}</div>${visible.length<resultIds.length?`<div class="more-row"><button class="button secondary" id="moreResults">${t('more')} · ${num(Math.min(36,resultIds.length-visible.length))}${icon('arrow')}</button></div>`:''}`;$('#moreResults')?.addEventListener('click',()=>{state.limit+=36;renderResults()})}
function renderAbout(){$('#main').innerHTML=`${crumb(t('aboutGuide'))}<article class="about-layout"><div class="eyebrow">YOGUI · MINECRAFT ${manifest.minecraft}</div><h1>${t('aboutTitle')}</h1><p>${t('aboutIntro')}</p><h2>${t('coverage')}</h2><table class="coverage-table"><tbody>${Object.entries(manifest.counts).map(([k,v])=>`<tr><td><a href="#view=catalog&kind=${k}">${esc(kindLabel(k))}</a></td><td>${num(v)}</td></tr>`).join('')}</tbody></table><h2>${t('howRead')}</h2><p>${t('aboutEvidence')}</p><p>${t('aboutVariants')}</p><p>${t('aboutLoot')}</p><h2>${t('limits')}</h2><p>${t('aboutLimits')}</p><p>${t('snapshot')}. ${t('jeiText')}</p><h2>${t('credits')}</h2><p>${t('aboutCredits')}</p><p>${t('fonts')} <a class="text-link" href="./assets/fonts/manrope-license.txt">Manrope</a> · <a class="text-link" href="./assets/fonts/lora-license.txt">Lora</a></p></article>`}
function nameOf(id){if(!id)return '';return L(names[id])||String(id).replace(/^#/,'').split(':').pop().replace(/[_/]/g,' ')}
function ingredient(value){
  const context=currentEntry?.kind==='recipe'?currentEntry.details:{};
  if(Array.isArray(value)){const candidates=value.map(ingredient);return {ids:candidates.flatMap(x=>x.ids),label:t('anyOf')+' '+candidates.map(x=>x.label).join(', '),tag:false}}
  if(typeof value==='string'){
    const tag=value.startsWith('#'),id=value.replace(/^#/,''),alias=!tag&&context?.ingredientAliases?.[id];
    const alternatives=tag&&context?.ingredientAlternatives?.[value];
    return {ids:alternatives?.length?alternatives:[id],label:L(context?.ingredientLabels?.[value])||(alias?L(alias.title):tag?`${t('tag')} · ${nameOf(id)}`:nameOf(id)),tag,image:alias?lookup.get(alias.itemId)?.image:null};
  }
  if(value&&typeof value==='object'){if(value.id)return ingredient(value.id);if(value.item)return ingredient(value.item);if(value.items)return ingredient(value.items);if(value.tag)return ingredient('#'+value.tag);if(value.ingredient)return ingredient(value.ingredient)}
  return {ids:[],label:t('unknownIngredient'),tag:false};
}
function ingredientIcon(i){if(i.image)return i.image;for(const id of i.ids){if(icons[id])return icons[id]}const tag=i.ids[0]?.split(':').pop()||'';const map={planks:'oak_planks',logs:'oak_log',logs_that_burn:'oak_log',wooden_slabs:'oak_slab',wool:'white_wool',stone_tool_materials:'cobblestone',flowers:'poppy',fishes:'cod',coals:'coal',arrows:'arrow',swords:'iron_sword',axes:'iron_axe',enchantable:'enchanted_book'};return icons['minecraft:'+(map[tag]||map[tag.split('/')[0]])]}
function cell(value,count=1,output=false){if(!value)return '<span class="craft-cell" aria-hidden="true"></span>';const i=ingredient(value);let src=ingredientIcon(i);if(output&&currentEntry){i.label=L(currentEntry.title);if(currentEntry.details?.resultItemId)src=lookup.get(currentEntry.details.resultItemId)?.image||src;}return `<span class="${output?'craft-output':'craft-cell filled'}" title="${esc(i.label)}" tabindex="0" aria-label="${esc(i.label)}">${src?imageTag(src,'',i.label):`<span class="fallback-item">${esc(i.label.slice(0,18))}</span>`}${i.tag?'<span class="tag-marker">#</span>':''}${count>1?`<span class="stack-count">${esc(count)}</span>`:''}</span>`}
function renderRecipe(entry){const d=entry.details||{};const kind=(d.type||'').split(':').pop();const result=d.stack||d.result||{};const output=cell(result,result.count||1,true);let body='',caption=L(d.workstation)||kind;let ingredients=[];
  if(kind==='crafting_shaped'){let grid=[];for(let row=0;row<3;row++){const p=d.pattern?.[row]||'';for(let col=0;col<3;col++){const ch=p[col]||' ';grid.push(cell(ch===' '?null:d.key?.[ch]));}}body=`<div class="craft-grid">${grid.join('')}</div><span class="craft-arrow">${icon('arrow')}</span>${output}`;ingredients=Object.values(d.key||{});caption=t('craftShaped')}
  else if(kind==='crafting_shapeless'){ingredients=d.ingredients||[];body=`<div class="craft-grid">${Array.from({length:9},(_,i)=>cell(ingredients[i])).join('')}</div><span class="craft-arrow">${icon('arrow')}</span>${output}`;caption=t('craftShapeless')}
  else if(kind==='crafting_transmute'){ingredients=[d.input,d.material];body=`<div class="craft-simple">${cell(d.input)}<span class="muted">+</span>${cell(d.material)}<span class="craft-arrow">${icon('arrow')}</span>${output}</div>`;caption=t('craftTransmute')}
  else if(kind.startsWith('smithing')){ingredients=[d.template,d.base,d.addition].filter(Boolean);body=`<div class="craft-simple">${ingredients.map(i=>cell(i)).join('<span class="muted">+</span>')}<span class="craft-arrow">${icon('arrow')}</span>${output}</div>`}
  else{ingredients=[d.ingredient||d.input].filter(Boolean);body=`<div class="craft-simple">${ingredients.map(i=>cell(i)).join('')}<span class="craft-arrow">${icon('arrow')}</span>${output}</div>`}
  return `<section class="detail-section"><h2>${t('craft')}</h2><div class="craft-panel">${body}</div><p class="craft-type">${esc(caption)}</p>${ingredients.length?`<div class="ingredients-list">${ingredients.map(v=>{const i=ingredient(v);const src=ingredientIcon(i);return `<span class="ingredient-pill">${src?imageTag(src,'',''):''}${esc(i.label)}</span>`}).join('')}</div>`:''}</section>`}
function numeric(value,level){if(typeof value==='number')return value;if(!value||typeof value!=='object')return null;const type=(value.type||'').split(':').pop();if(type==='linear')return (value.base||0)+(value.per_level_above_first||0)*(level-1);if(type==='levels_squared')return level*level+(value.added||0);if(type==='clamped'){const v=numeric(value.value,level);return v===null?null:Math.min(value.max??Infinity,Math.max(value.min??-Infinity,v))}if(type==='fraction'){const a=numeric(value.numerator,level),b=numeric(value.denominator,level);return a!==null&&b? a/b:null}if(type==='lookup')return value.values?.[level-1]??numeric(value.fallback,level);return null}
function renderEnchantment(entry,level=1){const d=entry.details||{};const max=d.maxLevel||1;const rules=d.rules||[];if(!rules.length)return '';return `<section class="detail-section"><div class="section-heading"><h2>${t('enchantEffects')}</h2>${max>1?`<label class="ingredient-pill">${t('level')} <select id="enchantLevel" class="filter-select">${Array.from({length:Math.min(max,255)},(_,i)=>`<option value="${i+1}" ${level===i+1?'selected':''}>${i+1}</option>`).join('')}</select></label>`:''}</div><div id="enchantRules">${rules.map(r=>{const effect=r.effect||{};const values=['value','amount','min_duration','max_duration'].map(k=>numeric(effect[k],level)).filter(v=>v!==null);return `<div class="fact" style="margin-bottom:9px"><div class="fact-label">${esc(L(r.label)||r.trigger||'')}</div><div class="fact-value">${esc(L(r.summary)||L(r.description)||'')}</div>${r.condition?`<p class="loot-note">${esc(L(r.condition))}</p>`:''}${values.length?`<p class="loot-note">${t('computedValue')} : ${values.map(v=>new Intl.NumberFormat(state.locale,{maximumFractionDigits:3}).format(v)).join(' · ')}</p>`:''}</div>`}).join('')}</div></section>`}
const asArray=value=>value==null?[]:Array.isArray(value)?value:[value];
const resourceID=value=>typeof value==='string'?(value.includes(':')?value:'minecraft:'+value):'';
function numberRange(value){if(value==null)return '1';if(typeof value!=='object')return String(value);if(value.min!=null||value.min_inclusive!=null)return `${numberRange(value.min??value.min_inclusive)}–${numberRange(value.max??value.max_inclusive)}`;if(value.n!=null)return `${value.n} × ${value.p??'?'}`;return humanType(value.type||'variable')}
function lootConditions(value){return [...asArray(value?.conditions),...asArray(typeof value?.condition==='object'?value.condition:null)]}
function conditionText(c){
  if(typeof c==='string')return humanType(c);
  const type=(c?.type||c?.condition||'').split(':').pop();
  const words={killed_by_player:['Tué par un joueur','Killed by a player'],survives_explosion:['Résiste à l’explosion','Survives the explosion'],location_check:['Lieu requis','Required location'],entity_properties:['Propriétés de la créature requises','Required entity properties'],'tool/can_silk_touch':['Outil avec Toucher de soie','Silk Touch tool'],match_tool:['Outil requis','Required tool'],table_bonus:['Bonus lié à l’enchantement','Enchantment-based bonus'],random_chance_with_enchanted_bonus:['Chance modifiée par l’enchantement','Enchantment-modified chance']};
  if(type==='random_chance')return (state.locale==='fr'?'Test aléatoire : ':'Random check: ')+(typeof c.chance==='number'?new Intl.NumberFormat(state.locale,{style:'percent',maximumFractionDigits:3}).format(c.chance):numberRange(c.chance));
  if(type==='inverted')return (state.locale==='fr'?'Sauf : ':'Unless: ')+conditionText(c.term||{});
  if(type==='all_of'||type==='any_of')return asArray(c.terms).map(conditionText).join(type==='all_of'?(state.locale==='fr'?' ET ':' AND '):(state.locale==='fr'?' OU ':' OR '));
  return words[type]?.[state.locale==='en'?1:0]||humanType(type);
}
const stableJSON=value=>JSON.stringify(value&&typeof value==='object'?(Array.isArray(value)?value.map(v=>JSON.parse(stableJSON(v))):Object.fromEntries(Object.keys(value).sort().map(k=>[k,JSON.parse(stableJSON(value[k]))]))):value);
function renderLoot(entry){
  const d=entry.details||{},pools=d.pools||d.table?.pools||d.raw?.pools||[];if(!pools.length)return '';
  const compiled=d.items||[];
  const modifiers=v=>[...asArray(v?.functions),...asArray(v?.modifier)];
  const conditionsHTML=cs=>cs.length?`<small>${t('condition')} · ${cs.map(c=>esc(conditionText(c))).join(' · ')}</small>`:'';
  function renderPools(list,depth=0,parentMods=[]){return list.map((pool,i)=>{
    const mods=[...parentMods,...modifiers(pool)],cs=lootConditions(pool);
    return `<div class="loot-pool"><div class="loot-pool-heading"><span>${t('pool')} ${i+1}</span><span>${esc(numberRange(pool.rolls??1))} ${t('rolls').toLowerCase()}</span></div>${cs.length?`<div class="loot-conditions">${conditionsHTML(cs)}</div>`:''}${renderNodes(pool.entries||[],depth,mods)}</div>`;
  }).join('')}
  function renderNodes(nodes,depth,parentMods){return nodes.map(row=>{
    const type=(row.type||'').split(':').pop(),mods=[...parentMods,...modifiers(row)],cs=lootConditions(row),weight=`${t('weight')} ${esc(row.weight??1)}`;
    const inline=type==='loot_table'&&row.value&&typeof row.value==='object';
    if(inline||['alternatives','sequence','group'].includes(type)){
      const names={alternatives:['Premier choix valide','First valid alternative'],sequence:['Séquence de choix','Choice sequence'],group:['Groupe d’entrées','Entry group']};
      const label=inline?t('nestedLoot'):names[type][state.locale==='en'?1:0];
      return `<details class="loot-nested" ${depth<1?'open':''}><summary><span>${esc(label)}</span><span>${weight}</span></summary>${conditionsHTML(cs)}<div class="loot-nested-content">${depth>15?'…':inline?renderPools(row.value.pools||[],depth+1,[...mods,...modifiers(row.value)]):renderNodes(row.children||[],depth+1,mods)}</div></details>`;
    }
    const identifier=resourceID(row.name||row.value),rawFunctions=new Set(mods.map(stableJSON));
    let candidates=type==='item'?compiled.filter(i=>resourceID(i.id)===identifier):[];
    if(candidates.length>1&&rawFunctions.size){const scored=candidates.map(c=>({c,n:asArray(c.functions).filter(f=>rawFunctions.has(stableJSON(f))).length}));const best=Math.max(...scored.map(v=>v.n));if(best)candidates=scored.filter(v=>v.n===best).map(v=>v.c)}
    const ids=[...new Set(candidates.map(c=>c.entryId))],candidate=ids.length===1?candidates[0]:null;
    const ref=type==='loot_table'?'loot:'+identifier:type==='item'?(candidate?.entryId||'item:'+identifier):null,known=lookup.get(ref);
    const label=known?L(known.title):candidate?L(candidate.name):type==='empty'?t('emptyLoot'):type==='loot_table'?`${t('nestedLoot')} · ${identifier}`:type==='tag'?`${t('tag')} · ${nameOf(identifier)}`:nameOf(identifier)||humanType(type);
    const src=known?.image||icons[ref]||icons[identifier];
    const countRule=mods.findLast(f=>(f.type||f.function||'').endsWith('set_count')),count=countRule?.count;
    return `<div class="loot-row">${src?imageTag(src,'',''):icon(type==='loot_table'?'loot':'item')}<span class="loot-name">${known?`<a class="text-link" href="${route({entry:ref})}">${esc(label)}</a>`:esc(label)}${count!=null?`<small>${state.locale==='fr'?'Quantité':'Amount'} · ${countRule?.add?'+':''}${esc(numberRange(count))}</small>`:''}${ids.length>1?`<small>${num(ids.length)} ${state.locale==='fr'?'variantes possibles · fiches ci-dessous':'possible variants · entries below'}</small>`:''}${conditionsHTML(cs)}</span><span class="loot-weight">${weight}</span></div>`;
  }).join('')}
  return `<section class="detail-section"><h2>${t('lootTitle')}</h2><p class="entry-section-caption">${t('lootNote')}</p>${renderPools(pools,0,modifiers(d))}</section>`;
}
function humanType(type){return String(type||'').split(':').pop().replace(/[_/]/g,' ')}
function factsHTML(facts){return facts.length?`<div class="facts-grid">${facts.map(f=>{const value=formatValue(f.value);return `<div class="fact ${value.length>180?'wide-fact':''}"><div class="fact-label">${esc(L(f.label))}</div><div class="fact-value">${value.length>270?`<details><summary>${esc(value.slice(0,170))}…</summary><div class="long-fact-body">${esc(value)}</div></details>`:esc(value)}</div></div>`}).join('')}</div>`:''}
function formatValue(value){const localized=L(value);if(typeof localized==='string')return localized;if(Array.isArray(value))return value.map(formatValue).join(', ');return JSON.stringify(value)}
function detailSections(entry){return (entry.sections||entry.details?.sections||[]).map(s=>`<section class="detail-section"><h2>${esc(L(s.title))}</h2>${textBlock(s.text||s.description)}</section>`).join('')}
function linkedHTML(entry){const groups=new Map();for(const raw of entry.links||[]){const ref=typeof raw==='string'?raw:raw.id;const e=lookup.get(ref);if(!e||e.id===entry.id)continue;const k=e.kind;if(!groups.has(k))groups.set(k,[]);if(!groups.get(k).some(a=>a.id===ref))groups.get(k).push(e)}return [...groups].map(([kind,entries])=>{const limit=linkLimits[kind]||18;return `<section class="detail-section"><h2>${kindLabel(kind)}</h2>${kind==='module'?`<p class="entry-section-caption">${t('moduleCaption')}</p>`:''}<div class="${kind==='module'?'module-list':'detail-links'}">${entries.slice(0,limit).map(e=>`<a class="detail-link" href="${route({entry:e.id})}">${iconForEntry(e)}<span><strong>${esc(L(e.title))}</strong><small>${esc(L(packs.get(e.pack)?.title)||e.pack)}</small></span><span class="link-arrow">${icon('arrow')}</span></a>`).join('')}</div>${entries.length>limit?`<button class="button quiet small" data-more-links="${kind}">${t('more')} · ${num(entries.length-limit)}</button>`:''}</section>`}).join('')}
async function getEntry(id){const r=lookup.get(id);if(!r)return null;if(!currentChunkCache.has(r.chunk)){if(!pendingChunkCache.has(r.chunk))pendingChunkCache.set(r.chunk,fetch('./data/entries/'+r.chunk).then(r=>{if(!r.ok)throw Error(r.status);return r.json()}).then(data=>{currentChunkCache.set(r.chunk,data);pendingChunkCache.delete(r.chunk);return data}));await pendingChunkCache.get(r.chunk)}return currentChunkCache.get(r.chunk)[id]}
function bindDetail(){document.querySelectorAll('[data-more-links]').forEach(b=>b.addEventListener('click',()=>{linkLimits[b.dataset.moreLinks]=(linkLimits[b.dataset.moreLinks]||18)+60;const y=$('#entryDialog').scrollTop;renderDetail(currentEntry);$('#entryDialog').scrollTop=y}));$('#enchantLevel')?.addEventListener('change',e=>{const selected=Number(e.target.value),top=$('#entryDialog').scrollTop;$('#enchEffects').innerHTML=renderEnchantment(currentEntry,selected);bindDetail();$('#entryDialog').scrollTop=top})}
function renderDetail(entry){currentEntry=entry;const p=packs.get(entry.pack);$('#dialogBreadcrumb').innerHTML=`<a href="#view=pack&pack=${encodeURIComponent(entry.pack)}">${esc(L(p?.title)||entry.pack)}</a> / ${esc(kindLabel(entry.kind,true))}`;$('#saveEntry').classList.toggle('saved',state.saved.has(entry.id));$('#saveEntry').setAttribute('aria-label',t(state.saved.has(entry.id)?'unsave':'save'));const alternate=state.locale==='fr'?entry.title.en:entry.title.fr;const body=`${entry.status!=='active'?`<div class="readable-notice">${t('disabledNotice')}</div>`:''}<header class="detail-heading">${iconForEntry(entry)}<div><div class="detail-kicker"><span class="kind-label">${kindLabel(entry.kind,true)}</span></div><h1 id="entryTitle">${esc(L(entry.title))}</h1>${alternate&&alternate!==L(entry.title)?`<p class="detail-original">${t('originalName')} · ${esc(alternate)}</p>`:''}</div></header><p class="detail-description">${esc(L(entry.description))}</p>${factsHTML(entry.facts||[])}${entry.kind==='recipe'?renderRecipe(entry):''}${entry.kind==='enchantment'?`<div id="enchEffects">${renderEnchantment(entry)}</div>`:''}${entry.kind==='loot'?renderLoot(entry):''}${detailSections(entry)}<div id="detailLinks">${linkedHTML(entry)}</div>${entry.tags?.length?`<div class="detail-tags">${entry.tags.slice(0,12).map(tag=>`<span class="detail-tag">${esc(tag)}</span>`).join('')}</div>`:''}<footer class="detail-source">${p?.url?`<a href="${safeURL(p.url)}" target="_blank" rel="noopener noreferrer">${t('officialPage')} · ${esc(L(p.title))}${icon('external')}</a>`:''}<span> · ${esc(p?.version||'')} · Minecraft ${esc(manifest.minecraft)}</span><details class="source-paths"><summary>${t('reference')}</summary><code>${esc(entry.id)}</code>${entry.details?.technicalFacts?.length?`<div class="technical-facts">${entry.details.technicalFacts.map(f=>`<p>${esc(L(f.label))} ? ${esc(formatValue(f.value))}</p>`).join('')}</div>`:''}${(entry.sourceFiles||[]).slice(0,35).map(path=>`<code>${esc(path)}</code>`).join('')}${entry.sourceFiles?.length>35?`<code>+ ${num(entry.sourceFiles.length-35)}</code>`:''}</details></footer>`;$('#entryContent').innerHTML=body;bindDetail()}
async function openEntry(id){const ticket=++entryRequest;if(currentEntry?.id!==id)linkLimits={};$('#entryContent').innerHTML=`<div class="initial-loading"><span class="loader"></span>${t('loading')}</div>`;if(!$('#entryDialog').open)$('#entryDialog').showModal();document.body.style.overflow='hidden';$('#entryDialog').scrollTop=0;try{const entry=await getEntry(id);if(ticket!==entryRequest)return;if(!entry){$('#entryContent').innerHTML=`<div class="empty-state"><h2 id="entryTitle">${t('notFound')}</h2></div>`;return}if(entry.kind==='pack'){closeEntry(false);go({view:'pack',pack:entry.pack,entry:null,q:'',kind:'all'});return}renderDetail(entry)}catch(error){console.error(error);$('#entryContent').innerHTML=`<div class="empty-state"><h2 id="entryTitle">${t('loadError')}</h2></div>`}}
function closeEntry(updateRoute=true){entryRequest++;if($('#entryDialog').open)$('#entryDialog').close();document.body.style.overflow='';currentEntry=null;if(updateRoute){history.replaceState(null,'',route({entry:null}));}}
function closeNav(){document.body.classList.remove('nav-open');$('#sidebarBackdrop').hidden=true;$('#menuButton').setAttribute('aria-expanded','false')}
function renderPage(){renderChrome();if(state.view==='home')renderHome();else if(state.view==='packs')renderPacks();else if(state.view==='pack')renderPack();else if(state.view==='about')renderAbout();else renderCatalog();$('#search').value=state.q;$('#searchClear').hidden=!state.q}
function readRoute(){const p=new URLSearchParams(location.hash.slice(1));const previous=state.view+'|'+state.kind+'|'+state.pack+'|'+state.q;state.view=p.get('view')||'home';if(!['home','catalog','packs','pack','saved','about'].includes(state.view))state.view='home';state.kind=p.get('kind')||'all';if(state.kind!=='all'&&!kinds[state.kind])state.kind='all';state.pack=p.get('pack')||'all';state.q=p.get('q')||'';state.sort=p.get('sort')||'relevance';state.disabled=p.get('disabled')==='1';state.limit=36;const entry=p.get('entry');renderPage();closeNav();if(entry)openEntry(entry);else closeEntry(false);if(previous!==state.view+'|'+state.kind+'|'+state.pack+'|'+state.q&&!entry)window.scrollTo({top:0,behavior:'instant'})}
function bindGlobal(){$('.skip-link').addEventListener('click',e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView({block:'start'})});window.addEventListener('hashchange',readRoute);$('#search').addEventListener('input',e=>{clearTimeout(searchTimer);state.q=e.target.value;$('#searchClear').hidden=!state.q;searchTimer=setTimeout(()=>{const next={view:state.view==='packs'?'packs':'catalog',q:state.q,entry:null};history.replaceState(null,'',route(next));state.view=next.view;state.limit=36;if(state.view==='packs')renderPacks();else renderCatalog();renderNav()},140)});$('#searchClear').addEventListener('click',()=>{state.q='';$('#search').value='';history.replaceState(null,'',route({q:'',entry:null}));renderPage();$('#search').focus()});document.querySelectorAll('[data-language]').forEach(b=>b.addEventListener('click',()=>{state.locale=b.dataset.language;store.set('yogui-language',state.locale);renderPage();const id=new URLSearchParams(location.hash.slice(1)).get('entry');if(id)openEntry(id)}));$('#bookmarksButton').addEventListener('click',()=>go({view:'saved',kind:'all',pack:'all',q:'',entry:null}));$('#menuButton').addEventListener('click',()=>{const open=document.body.classList.toggle('nav-open');$('#sidebarBackdrop').hidden=!open;$('#menuButton').setAttribute('aria-expanded',String(open))});$('#sidebarBackdrop').addEventListener('click',closeNav);$('#closeEntry').addEventListener('click',()=>closeEntry());$('#entryDialog').addEventListener('cancel',e=>{e.preventDefault();closeEntry()});$('#entryDialog').addEventListener('click',e=>{if(e.target===$('#entryDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeEntry()}});$('#saveEntry').addEventListener('click',()=>currentEntry&&save(currentEntry.id));$('#copyEntry').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(location.href);showToast(t('copied'))}catch{showToast(location.href)}});document.addEventListener('click',e=>{const button=e.target.closest('[data-save]');if(button){e.preventDefault();save(button.dataset.save)}});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if($('#entryDialog').open)closeEntry();$('#search').focus();$('#search').select()}if(e.key==='Escape')closeNav()});}
async function init(){try{const files=await Promise.all(['manifest','index','icons','names'].map(name=>fetch('./data/'+name+'.json',{cache:'no-cache'}).then(r=>{if(!r.ok)throw Error(name+' '+r.status);return r.json()})));[manifest,{entries:index},icons,names]=files;lookup=new Map(index.map(e=>[e.id,e]));packs=new Map([...manifest.packs,...(manifest.referencePack?[manifest.referencePack]:[])].map(p=>[p.id,p]));worker=new Worker(new URL('./search-worker.js',import.meta.url));worker.onmessage=event=>{if(event.data.type==='ready'){workerReady=true;query()}if(event.data.type==='results'&&event.data.request===request){resultIds=event.data.ids;renderResults()}};worker.postMessage({type:'init',entries:index});bindGlobal();readRoute()}catch(error){console.error(error);$('#main').innerHTML=`<div class="empty-state"><h1>Le carnet n’a pas pu s’ouvrir.</h1><p>${esc(error.message)}. Utilisez le site via GitHub Pages ou un serveur HTTP local.</p><button class="button" onclick="location.reload()">Réessayer</button></div>`}}
init();
